import assert from 'node:assert/strict';
for(const key of ['document','window','localStorage'])Object.defineProperty(globalThis,key,{configurable:true,get(){throw Error('Headless vehicle API accessed '+key);}});
const {createVehicleYard,vehicleYardContent,VEHICLE_BODIES}=await import('@nautilus-engine/map-core/vehicles');
const pin=process.argv[2],results=[];
for(const body of VEHICLE_BODIES){const content=vehicleYardContent({sourcePin:pin});content.vehicles[0].body=body.id;const yard=createVehicleYard(content),s=yard.connector,resources=yard.read().resources;
 const board=s.dispatch({version:1,type:'board',actorId:'player',vehicleId:'compact',seatId:'driver',expected:s.readForActor('player').expected});assert.equal(board.ok,true,JSON.stringify(board));assert.equal(s.readForActor('player').mode,'driver');
 const initial=s.read().vehicles[0];assert.equal(s.dispatch({version:1,type:'control',actorId:'player',owner:'installed-keyboard',expected:s.readForActor('player').expected,throttle:1,steering:.4,held:true}).ok,true);for(let i=0;i<20;i++)yard.advance(.05);const moved=s.read().vehicles[0];assert.ok(moved.position.y>initial.position.y+.5);const right={x:-Math.cos(initial.headingRad),y:Math.sin(initial.headingRad)};assert.ok(Math.sin(moved.headingRad)*right.x+Math.cos(moved.headingRad)*right.y>0);assert.ok((moved.position.x-initial.position.x)*right.x+(moved.position.y-initial.position.y)*right.y>0);
 const saved=yard.checkpoint(),restored=createVehicleYard(content,{checkpoint:saved});assert.deepEqual(restored.checkpoint(),saved);assert.equal(restored.connector.readForActor('player').lease,null);assert.deepEqual(restored.read().resources,resources);for(let i=0;i<20;i++)restored.advance(.05);assert.equal(restored.connector.read().vehicles[0].speedMps,0);assert.equal(restored.connector.dispatch({version:1,type:'exit',actorId:'player',expected:restored.connector.readForActor('player').expected}).ok,true);assert.equal(restored.readPose().mode,'on-foot');assert.deepEqual(restored.read().resources,resources);results.push({body:body.id,wheelbaseM:initial.wheelbaseM,distanceM:moved.distanceM,headingRad:moved.headingRad,resourcesPreserved:true});yard.dispose();restored.dispose();}
console.log(JSON.stringify({status:'passed',headless:true,bodyProofs:results}));
